'use strict';
// Voice packs (语音包, docs/voice-packs.md): her fixed lines recorded ahead, played straight from disk — no key, no network,
// no per-minute limit (MiniMax allows 10 a minute). Agent replies are not fixed and still go to an engine.
//
// A pack is a folder: manifest.json + audio files.
//   { "format": 1, "id": "dafeiyu-minimax", "name": "…", "character": "dafeiyu",
//     "engine": "minimax", "voiceId": "qiaopi_mengmei", "model": "speech-2.8-turbo", "credit": "…",
//     "lines": { "<line as read>": "<file>.mp3", … } }
// Built-in packs live in src/voicepacks/<id>/ (generated by scripts/voicepack-generate.js); packs the
// owner adds go in userData/voicepacks/<id>/ and win over a built-in one for the same character.
// A line is looked up exactly as it is sent to an engine (speakable text, one sentence or a whole short line).
//
// Two kinds (`kind`, absent = "character", every pack before generic ones existed):
//   character — 专属语音包: one character's own lines in her voice; `character` names her.
//   generic   — 通用语音包: lines any companion may say (app, stage and touch lines, no names), in a voice of
//               one `gender` ("female" | "male"); no `character`. `engine` + `voiceId` (+ `model`, `params`)
//               are required: they are also the default engine voice of a character who falls back to this
//               pack and whose file names no voice.tts (voiceForPack), so her agent replies sound the same.
//     { "format": 1, "kind": "generic", "gender": "male", "id": "generic-male", "name": "…",
//       "engine": "minimax", "voiceId": "male-qn-qingse", "model": "…", "params": { … }, "lines": { … } }
// Which pack a character uses (resolvePack): the one the owner picked for her (settings.tts.voicePackByCharacter)
// > her own (专属) > the generic pack of her gender (core/voice-gender.js).

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const Voice = require('./voice');
const dialogue = require('./dialogue');
const touchZones = require('./touch-zones');
const IVoice = require('./interaction-voice');
const Gender = require('./voice-gender');

const FORMAT = 1;
const KINDS = ['character', 'generic'];
const PACK_ID_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;
// engines a generic pack's default voice may be on (the local server's voice is the owner's, not a pack's)
const VOICE_ENGINES = ['fish', 'minimax', 'elevenlabs'];
const AUTO = 'auto';
const MIME = { mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg', opus: 'audio/opus' };
// what main.js does to a line before it reaches an engine (core/tts.js synthesize)
const norm = (text) => String(text || '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const fileFor = (text, ext = 'mp3') => `${crypto.createHash('sha1').update(norm(text)).digest('hex').slice(0, 16)}.${ext}`;

// Lines the app itself says outside the character files (pet-service.js).
const APP_LINES = ['呃……肚子圆滚滚的，吃不下了。', '好累……让我睡一会儿。', '哈——睡饱啦。'];
// Parts of a character file that are never read aloud.
const SKIP_KEYS = new Set(['id', 'order', 'vendor', 'model', 'models', 'name', 'nameZh', 'title', 'accent', 'blurb', 'personality', 'likes', 'art', 'fx', 'credits', 'signature', 'outfits', 'memes', 'adult', 'tts', 'lang', 'prefer', 'zones', 'videoBox', 'poses']);

const strings = (o, out = []) => {
  if (typeof o === 'string') { if (/[㐀-鿿]/.test(o)) out.push(o); }
  else if (Array.isArray(o)) o.forEach((x) => strings(x, out));
  else if (o && typeof o === 'object') for (const [k, v] of Object.entries(o)) if (!SKIP_KEYS.has(k)) strings(v, out);
  return out;
};

// Every fixed line she may say, as it is sent to an engine: the whole line (interaction lines and murmurs
// are read whole) and each sentence of it (replies and milestones are read sentence by sentence).
function packLines(species) {
  const raw = [
    ...strings(species),
    ...strings(dialogue.STAGE_LINES),
    ...strings(touchZones.DEFAULT_LINES),
    ...strings(touchZones.ADULT_LINES),
    ...APP_LINES,
  ];
  const out = new Set();
  for (const line of raw) {
    const whole = norm(Voice.speakable(line));
    if (whole) out.add(whole);
    for (const p of Voice.sentences(line)) if (p.say) out.add(norm(p.say));
  }
  return [...out];
}

// Every line a 通用语音包 holds: what any companion may say whatever her file — the app's own lines, the
// relationship-stage lines, the default touch-zone and drag / throw / catch lines and the lines of the
// generic companion's template (core/generic.js) that carry no name. Never a character's own lines.
function genericPackLines() {
  const G = require('./generic');
  const NAME = '\u0000name\u0000';
  const template = G.characterFor({ id: 'generic-voice', name: NAME });
  const raw = [
    ...strings(dialogue.STAGE_LINES),
    ...strings(touchZones.DEFAULT_LINES),
    ...strings(IVoice.DEFAULT_LINES),
    ...strings(template.fallback).filter((l) => !l.includes(NAME)),
    ...APP_LINES,
  ];
  const out = new Set();
  for (const line of raw) {
    const whole = norm(Voice.speakable(line));
    if (whole) out.add(whole);
    for (const p of Voice.sentences(line)) if (p.say) out.add(norm(p.say));
  }
  return [...out];
}

const kindOf = (m) => (m && m.kind === 'generic' ? 'generic' : 'character');

// Problems with a manifest (empty = valid). `dir` checks that every file is there.
function validateManifest(m, dir = null) {
  const errors = [];
  if (!m || typeof m !== 'object') return ['manifest.json must be an object'];
  if (m.format !== FORMAT) errors.push(`format must be ${FORMAT}`);
  if (m.kind !== undefined && !KINDS.includes(m.kind)) errors.push(`kind must be one of ${KINDS.join(', ')}`);
  const generic = kindOf(m) === 'generic';
  for (const k of generic ? ['id', 'name'] : ['id', 'name', 'character']) if (typeof m[k] !== 'string' || !m[k].trim()) errors.push(`${k} is required`);
  if (m.id && !PACK_ID_RE.test(m.id)) errors.push('id: lowercase letters, digits and -');
  if (m.id === AUTO) errors.push(`id ${AUTO} is reserved`);
  if (generic) {
    if (!Gender.isGender(m.gender)) errors.push(`gender is required for a generic pack (one of ${Gender.GENDERS.join(', ')})`);
    if (m.character !== undefined) errors.push('a generic pack belongs to no character (leave character out)');
    if (!VOICE_ENGINES.includes(m.engine)) errors.push(`engine is required for a generic pack (one of ${VOICE_ENGINES.join(', ')}): its voice reads for characters without one`);
    if (typeof m.voiceId !== 'string' || !m.voiceId.trim()) errors.push('voiceId is required for a generic pack');
    else if (VOICE_ENGINES.includes(m.engine) && (m.params === undefined || (m.params && typeof m.params === 'object' && !Array.isArray(m.params)))) {
      // the voice as a character file would name it (core/tts.js validateVoice): a real voice id, params in range
      errors.push(...require('./tts').validateVoice({ tts: packVoiceTts(m) }).map((e) => `engine voice: ${e}`));
    }
  } else if (m.gender !== undefined) errors.push(...Gender.validateGender(m.gender));
  if (m.params !== undefined && (!m.params || typeof m.params !== 'object' || Array.isArray(m.params))) errors.push('params must be an object');
  if (!m.lines || typeof m.lines !== 'object' || Array.isArray(m.lines)) errors.push('lines must map each line to its audio file');
  else for (const [text, file] of Object.entries(m.lines)) {
    if (!norm(text) || typeof file !== 'string' || !/^[\w.-]+\.(mp3|wav|ogg|opus)$/.test(file) || file.includes('..')) { errors.push(`lines: bad entry for "${text.slice(0, 20)}"`); break; }
    if (dir && !fs.existsSync(path.join(dir, file))) { errors.push(`lines: missing file ${file}`); break; }
  }
  return errors;
}

class VoicePacks {
  // dirs: folders that hold one pack per subfolder, later ones winning (built-in first, the owner's last)
  constructor(dirs = [], { log = () => {} } = {}) {
    this.dirs = dirs;
    this.log = log;
    this.reload();
  }

  reload() {
    this.byCharacter = {}; // character -> her own pack (专属)
    this.byId = {}; // pack id -> pack, every kind
    this.generic = {}; // gender -> the generic pack (通用)
    this.errors = [];
    for (const root of this.dirs) {
      let names = [];
      try { names = fs.readdirSync(root, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name); } catch { continue; }
      for (const name of names.sort()) {
        const dir = path.join(root, name);
        try {
          const m = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));
          const errors = validateManifest(m, dir);
          if (errors.length) { this.errors.push({ dir, errors }); this.log(new Error(`voice pack ${dir}: ${errors.join('; ')}`)); continue; }
          const lines = new Map(Object.entries(m.lines).map(([t, f]) => [norm(t), f]));
          const pack = { ...m, kind: kindOf(m), gender: m.gender || null, dir, lines, builtIn: root === this.dirs[0] };
          if (pack.kind === 'generic') pack.character = null;
          // a later pack with the same id (the owner's) replaces the earlier one everywhere
          const old = this.byId[pack.id];
          if (old && old.kind === 'generic' && this.generic[old.gender] === old) delete this.generic[old.gender];
          if (old && old.kind === 'character' && this.byCharacter[old.character] === old) delete this.byCharacter[old.character];
          this.byId[pack.id] = pack;
          if (pack.kind === 'generic') this.generic[pack.gender] = pack;
          else this.byCharacter[pack.character] = pack;
        } catch (e) {
          this.errors.push({ dir, errors: [e.message] });
        }
      }
    }
  }

  // her own pack (专属), or null — what every caller got before generic packs existed
  packFor(characterId) {
    return this.byCharacter[characterId] || null;
  }

  get(packId) {
    return (typeof packId === 'string' && Object.hasOwn(this.byId, packId) && this.byId[packId]) || null;
  }

  genericFor(gender) {
    return this.generic[gender] || null;
  }

  // every pack in use (a replaced one is not listed): her own packs first, then the generic ones
  list() {
    const live = Object.values(this.byId).filter((p) => (p.kind === 'generic' ? this.generic[p.gender] === p : this.byCharacter[p.character] === p));
    return [...live.filter((p) => p.kind === 'character'), ...live.filter((p) => p.kind === 'generic')]
      .map((p) => ({ id: p.id, name: p.name, kind: p.kind, gender: p.gender || null, character: p.character || null, engine: p.engine || null, voiceId: p.voiceId || null, credit: p.credit || '', lines: p.lines.size, builtIn: p.builtIn }));
  }

  // The recorded line in her own pack, or null. { audio, mime, provider: 'pack', packId, engine, voiceId }
  lookup(characterId, text) {
    return this.lookupIn(this.packFor(characterId), text);
  }

  // The recorded line in `p` (any kind), or null.
  lookupIn(p, text) {
    const file = p && p.lines && p.lines.get(norm(text));
    if (!file) return null;
    try {
      const audio = fs.readFileSync(path.join(p.dir, file));
      return { audio, mime: MIME[path.extname(file).slice(1)] || 'audio/mpeg', provider: 'pack', packId: p.id, engine: p.engine || null, voiceId: p.voiceId || null };
    } catch {
      return null;
    }
  }
}

// Whether a recorded line should be played instead of asking an engine: packs on, and the engine that
// would read this line is the one the pack was recorded with — or there is no engine she could use at
// all (a recorded line beats the system voice). With 系统语音 chosen, never.
function packApplies(tts, pack, firstEngine) {
  if (!pack || !tts || tts.packs === false || tts.provider === 'system') return false;
  return !firstEngine || !pack.engine || firstEngine === pack.engine;
}

// Which pack a character uses. Pure: `packs` is anything with get(id) / packFor(character) / genericFor(gender)
// (a VoicePacks). choice: the owner's pick for her (settings.tts.voicePackByCharacter[id]: a pack id, or 'auto'
// / missing); a pick whose pack is gone counts as 'auto'. gender: hers (core/voice-gender.js genderOf).
// → { pack, source: 'user' | 'own' | 'generic' | null, choice: packId | 'auto', missing: packId | null }
function resolvePack({ characterId, gender, choice } = {}, packs) {
  const picked = typeof choice === 'string' && choice !== AUTO ? choice : null;
  const chosen = picked && packs ? packs.get(picked) : null;
  if (chosen) return { pack: chosen, source: 'user', choice: picked, missing: null };
  const missing = picked;
  const own = packs && characterId ? packs.packFor(characterId) : null;
  if (own) return { pack: own, source: 'own', choice: AUTO, missing };
  const g = Gender.isGender(gender) ? gender : Gender.DEFAULT_GENDER;
  const generic = packs ? packs.genericFor(g) : null;
  if (generic) return { pack: generic, source: 'generic', choice: AUTO, missing };
  return { pack: null, source: null, choice: AUTO, missing };
}

// A pack's voice as a character file's voice.tts (core/tts.js PROVIDERS[engine].config reads it).
function packVoiceTts(pack) {
  if (!pack || !VOICE_ENGINES.includes(pack.engine) || typeof pack.voiceId !== 'string' || !pack.voiceId.trim()) return null;
  const params = pack.params && typeof pack.params === 'object' ? Object.fromEntries(Object.entries(pack.params).filter(([, v]) => v !== undefined && v !== null && v !== '')) : {};
  const own = pack.engine === 'fish' ? { referenceId: pack.voiceId } : { voiceId: pack.voiceId };
  return { default: pack.engine, [pack.engine]: { ...params, ...own, ...(typeof pack.model === 'string' && pack.model ? { model: pack.model } : {}) } };
}

// The species an engine reads a line for, given the pack she resolved to: her own voice stays hers (a
// character whose file names voice.tts sounds exactly as before), except that a pack the owner picked for her
// brings its voice along, so recorded and synthesised lines are one voice. A character without voice.tts who
// falls back to a generic pack reads with that pack's voice (a new imported model: the generic male / female
// voice). Pure; returns `species` itself when nothing changes.
function voiceForPack(species, resolved) {
  const pack = resolved && resolved.pack;
  const tts = packVoiceTts(pack);
  if (!species || !tts) return species;
  const v = species.voice && typeof species.voice === 'object' ? species.voice : null;
  const hasOwn = !!(v && v.tts && typeof v.tts === 'object' && Object.keys(v.tts).length);
  const userPicked = resolved.source === 'user' && pack.character !== species.id;
  if (!userPicked && (hasOwn || pack.kind !== 'generic')) return species;
  return { ...species, voice: { ...(v || {}), tts } };
}

module.exports = { FORMAT, KINDS, AUTO, PACK_ID_RE, VOICE_ENGINES, APP_LINES, norm, fileFor, packLines, genericPackLines, validateManifest, VoicePacks, packApplies, resolvePack, packVoiceTts, voiceForPack };
